#include <stdio.h>

int main() {
    FILE *fp = fopen("notes.txt", "w");
    if (fp == NULL) {
        printf("Could not open file for writing\n");
        return 1;
    }
    fprintf(fp, "Line one\nLine two\n");
    fclose(fp);

    fp = fopen("notes.txt", "r");
    if (fp == NULL) {
        printf("Could not open file for reading\n");
        return 1;
    }
    char buffer[100];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        printf("%s", buffer);
    }
    fclose(fp);
    return 0;
}
